// project initialization
namespace SpriteKind {
    export let Canvas = SpriteKind.create()
    export let Palette = SpriteKind.create()
}

let paintColors = [6, 7, 8, 9, 10, 11]
let currentColor = 13
let brushColor = 11

// project start
let background = sprites.create(assets.image`canvasBackground`, SpriteKind.Canvas)

let paintBrushSprite = sprites.create(assets.image`paintBrush`, SpriteKind.Player)
paintBrushSprite.z = 5
controller.moveSprite(paintBrushSprite, 50, 50)
paintBrushSprite.setPosition(14, 20)

for (let index = 0; index <= (paintColors.length - 1); index++) {
    let circle = sprites.create(assets.image`emptyPaint`, SpriteKind.Palette)
    circle.setPosition(30 + 20 * index, 20)
    circle.image.replace(0, 6)
}

// project events
game.onUpdate(function () {
    if (controller.A.isPressed()) {
        background.image.setPixel(0, 0, 0)
    }
})

sprites.onOverlap(SpriteKind.Player, SpriteKind.Palette, function (sprite, otherSprite) {
    sprite.image.replace(brushColor, currentColor)
    brushColor = currentColor
})
